def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C' if history[-1][1] == 'C' else 'D'
    rounds_left = 100 - n
    if rounds_left <= 1:
        return 'D'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = me.count('C')
    my_d = n - my_c
    last_opp = opp[-1]
    last_my = me[-1]
    if opp_d == 0:
        if n >= 60:
            return 'D'
        if n >= 25 and n % 11 == 0:
            return 'D'
        return 'C'
    if opp_c == 0:
        return 'D'
    window = 12 if n >= 12 else n
    recent = history[-window:]
    recent_opp_d = sum(1 for a, b in recent if b == 'D')
    recent_my_d = sum(1 for a, b in recent if a == 'D')
    recent_opp_c = window - recent_opp_d
    if recent_opp_d * 3 >= window * 2:
        return 'D'
    if n >= 8 and recent_opp_d >= 5:
        return 'D'
    opp_after_my_c = 0
    opp_after_my_c_d = 0
    opp_after_my_d = 0
    opp_after_my_d_d = 0
    for i in range(n - 1):
        if me[i] == 'C':
            opp_after_my_c += 1
            if opp[i + 1] == 'D':
                opp_after_my_c_d += 1
        else:
            opp_after_my_d += 1
            if opp[i + 1] == 'D':
                opp_after_my_d_d += 1
    p_after_c = opp_after_my_c_d / opp_after_my_c if opp_after_my_c > 0 else 0.0
    p_after_d = opp_after_my_d_d / opp_after_my_d if opp_after_my_d > 0 else 0.0
    if n >= 15 and opp_after_my_d >= 4 and p_after_d >= 0.85 and p_after_c >= 0.7:
        return 'D'
    if last_opp == 'D':
        if n >= 3 and opp[-2] == 'D' and opp[-3] == 'D':
            return 'D'
        if n >= 6 and opp[-6:].count('D') >= 3:
            return 'D'
        if n >= 12 and p_after_c >= 0.4 and recent_opp_c >= 8:
            return 'C'
        if n >= 25 and opp_c * 3 >= n * 2 and recent_opp_d <= 1:
            if rng.random() < 0.35:
                return 'C'
        if n >= 40 and opp_c * 4 >= n * 3 and recent_opp_d <= 2:
            if rng.random() < 0.5:
                return 'C'
        return 'D'
    if n >= 70 and opp_c * 5 >= n * 4:
        if rng.random() < 0.4:
            return 'D'
        return 'C'
    if n >= 30 and recent_opp_d == 0 and recent_my_d >= 3:
        return 'C'
    if n >= 20 and recent_opp_c == window and my_d > my_c:
        return 'C'
    if n >= 50 and opp_c * 17 >= n * 16:
        if n % 9 == 0:
            return 'D'
        return 'C'
    return 'C'
